-- Phase 2: identity, project setup, documents, payments, notifications and reporting support.
create table public.invitations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,email text,phone text,role public.app_role not null,project_id uuid references public.projects(id) on delete cascade,token_hash text not null unique,expires_at timestamptz not null,accepted_at timestamptz,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),check(email is not null or phone is not null));
create table public.buildings(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,name text not null,wings int not null default 1 check(wings>0),floors int not null default 1 check(floors>0),area_sqft numeric(14,2) not null default 0 check(area_sqft>=0),unique(project_id,name));
create table public.boq_items(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,activity_id uuid references public.activities(id) on delete set null,code text not null,description text not null,quantity numeric(14,3) not null check(quantity>=0),unit text not null,rate numeric(16,2) not null check(rate>=0),manufacturer text,version int not null default 1 check(version>0),created_at timestamptz not null default now(),unique(project_id,code,version));
create table public.document_access(document_id uuid not null references public.documents(id) on delete cascade,role public.app_role not null,primary key(document_id,role));
create table public.notifications(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),recipient_id uuid not null references public.profiles(id),event text not null,title text not null,body text not null,channels text[] not null default array['IN_APP'],read_at timestamptz,created_at timestamptz not null default now());
create table public.payment_records(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.invoices(id),provider text not null check(provider in ('RAZORPAY','INTERNAL')),provider_payment_id text,amount numeric(16,2) not null check(amount>=0),currency char(3) not null default 'INR',status text not null check(status in ('PENDING','CAPTURED','FAILED')),created_at timestamptz not null default now());
create table public.project_holidays(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,holiday_date date not null,label text not null,unique(project_id,holiday_date));
create index on public.invitations(tenant_id,expires_at); create index on public.boq_items(project_id,version); create index on public.notifications(recipient_id,read_at,created_at desc); create index on public.payment_records(invoice_id,status);
alter table public.invitations enable row level security; alter table public.buildings enable row level security; alter table public.boq_items enable row level security; alter table public.document_access enable row level security; alter table public.notifications enable row level security; alter table public.payment_records enable row level security; alter table public.project_holidays enable row level security;
create policy "tenant invitation access" on public.invitations for all using (tenant_id=(select tenant_id from public.profiles where id=auth.uid())) with check (tenant_id=(select tenant_id from public.profiles where id=auth.uid()));
create policy "building access" on public.buildings for all using (public.can_access_project(project_id)) with check (public.can_access_project(project_id));
create policy "boq access" on public.boq_items for all using (public.can_access_project(project_id)) with check (public.can_access_project(project_id));
create policy "document acl access" on public.document_access for select using (exists(select 1 from public.documents d where d.id=document_id and public.can_access_project(d.project_id)));
create policy "notification recipient access" on public.notifications for select using (recipient_id=auth.uid());
create policy "payment record access" on public.payment_records for select using (exists(select 1 from public.invoices i where i.id=invoice_id and public.can_access_project(i.project_id)));
create policy "holiday access" on public.project_holidays for all using (public.can_access_project(project_id)) with check (public.can_access_project(project_id));
create function public.prevent_audit_mutation() returns trigger language plpgsql as $$begin raise exception 'audit_events are immutable'; end;$$;
create trigger audit_events_immutable before update or delete on public.audit_events for each row execute function public.prevent_audit_mutation();
create function public.report_portfolio() returns table(project_count bigint,contract_value numeric,activity_progress numeric) language sql stable security invoker set search_path=public as $$select count(distinct p.id),coalesce(sum(distinct p.contract_value),0),coalesce(avg(a.progress),0) from projects p left join activities a on a.project_id=p.id where can_access_project(p.id)$$;
